/// <summary>
/// Extension classe for <c>SalesTableType</c> class
/// </summary>
[ExtensionOf(classStr(SalesTableType))]
public final class METSalesTableType_Extension
{
}

Method.Source:
    /// <summary>
    /// Update Extract status
    /// </summary>
    public void metUpdateExtractStatus()
    {
        SalesLine       salesLine;
        METSalesLine    metSalesLine;

        select minof(OrderExtractStatus) from metSalesLine
            exists join salesLine
                where metSalesLine.SalesLine == salesLine.RecId &&
                    salesLine.SalesId == salesTable.SalesId;

        if (salesTable)
        {
            ttsbegin;
            salesTable.reread();
            salesTable.selectforupdate(true);
            salesTable.METOrderExtractStatus = metSalesLine.OrderExtractStatus;
            salesTable.SkipUpdate   = InterCompanySkipUpdate::Both;
            salesTable.update();
            ttscommit;
        }
    }

    /// <summary>
    /// Determine the confirmation br updated.
    /// </summary>
    /// <param name = "_documentStatus">Document status</param>
    /// <returns>Boolean true or false</returns>
    boolean  canConfirmationBeUpdated(DocumentStatus _documentStatus)
    {
        boolean ret = next canConfirmationBeUpdated( _documentStatus);

       // CB175-SalesConfirmation-start
        if (!ret && _documentStatus == DocumentStatus::Confirmation)
        {
            METCustParameters metCustParameters = METCustParameters::find();
            if (salesTable.salesStatus == SalesStatus::Canceled
                && metCustParameters.IncludeCancelledLines)
            {
                ret = true;
            }
        }
        // CB175-SalesConfirmation-end

        return ret;
    }

    /// <summary>
    /// May confirmation be updated
    /// </summary>
    /// <returns>True or false</returns>
    boolean mayConfirmationBeUpdated()
    {
        boolean             ok = next mayConfirmationBeUpdated();
        METCustParameters   metCustParameters = METCustParameters::find();
        
        //CB175-SalesConfirmation-start
        if (!ok && metCustParameters.IncludeCancelledLines)
        //CB175-SalesConfirmation-end
        {
            ok = (!(salesTable.SalesStatus  == SalesStatus::Invoiced ||
                SalesTable.SalesStatus  == SalesStatus::Delivered) &&
                (salesTable.mcrOrderStopped == NoYes::No ||
                !isConfigurationkeyEnabled(configurationKeyNum(MCRCallCenter)))
                    );
        }

        return ok;
    }
